public class PeakFinderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("peakIndices({1,3,2,4,1})", "[1, 3]",
                    java.util.Arrays.toString(PeakFinder.peakIndices(new int[]{1, 3, 2, 4, 1})));
            check("peakIndices({1,3,3,1}) plateau is not a peak", "[]",
                    java.util.Arrays.toString(PeakFinder.peakIndices(new int[]{1, 3, 3, 1})));
            check("peakIndices({1,2,3,4,5}) increasing has none", "[]",
                    java.util.Arrays.toString(PeakFinder.peakIndices(new int[]{1, 2, 3, 4, 5})));
            check("peakIndices({0,9,0}) single peak", "[1]",
                    java.util.Arrays.toString(PeakFinder.peakIndices(new int[]{0, 9, 0})));
            check("peakIndices({5,1}) too short for peaks", "[]",
                    java.util.Arrays.toString(PeakFinder.peakIndices(new int[]{5, 1})));
            check("peakIndices({}) empty", "[]",
                    java.util.Arrays.toString(PeakFinder.peakIndices(new int[]{})));
            check("peakIndices({2,7,2,7,2,7,2}) alternating", "[1, 3, 5]",
                    java.util.Arrays.toString(PeakFinder.peakIndices(new int[]{2, 7, 2, 7, 2, 7, 2})));
            check("peakIndices({-3,-1,-2}) negative peak", "[1]",
                    java.util.Arrays.toString(PeakFinder.peakIndices(new int[]{-3, -1, -2})));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception: " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

