public class PeakFinder {

    public static int[] peakIndices(int[] a) {
        int[] found = new int[a.length];
        int count = 0;
        for (int i = 1; i < a.length - 1; i++) {
            if (a[i] > a[i - 1] && a[i] > a[i + 1]) {
                found[count++] = i;
            }
        }
        return java.util.Arrays.copyOf(found, count);
    }
}
